1	package netdiag
2	
3	import (
4		"errors"
5		"reflect"
6		"strings"
7		"testing"
8		"unicode"
9		"unicode/utf8"
10	
11		"github.com/charmbracelet/x/ansi"
12	
13		"github.com/anthnel/devdesk/internal/docker"
14	)
15	
16	const (
17		idWeb = "aaaaaaaaaaaa"
18		idDB  = "bbbbbbbbbbbb"
19		idAPI = "cccccccccccc"
20		idHos = "dddddddddddd"
21	)
22	
23	func ctr(id, name, image, state string) docker.Container {
24		return docker.Container{ID: id, Name: name, Image: image, State: state}
25	}
26	
27	func sourceNames(l pathSourceList) []string {
28		names := []string{}
29		for _, s := range l.Containers {
30			names = append(names, s.Name)
31		}
32		return names
33	}
34	
35	func assertDisplaySafe(t *testing.T, what, s string) {
36		t.Helper()
37		if !utf8.ValidString(s) {
38			t.Errorf("%s %q is not valid UTF-8", what, s)
39		}
40		if ansi.Strip(s) != s || strings.ContainsRune(s, '\x1b') {
41			t.Errorf("%s %q carries an escape sequence", what, s)
42		}
43		for _, r := range s {
44			if unicode.Is(unicode.Cc, r) || unicode.Is(unicode.Cf, r) {
45				t.Errorf("%s %q carries control/format rune %U", what, s, r)
46			}
47		}
48		if n := utf8.RuneCountInString(s); n > 128 {
49			t.Errorf("%s is %d runes, want <= 128", what, n)
50		}
51	}
52	
53	func TestPathSourceHost(t *testing.T) {
54		h := hostSource()
55		if !h.isHost() {
56			t.Error("hostSource().isHost() = false")
57		}
58		if h.ID != "" {
59			t.Errorf("host ID = %q, want empty", h.ID)
60		}
61		if got := h.label(); got != "this machine" {
62			t.Errorf("host label = %q, want %q", got, "this machine")
63		}
64		c := pathSource{ID: idWeb, Name: "web-1"}
65		if c.isHost() {
66			t.Error("a container source reports isHost")
67		}
68		if got := c.label(); got != "web-1" {
69			t.Errorf("container label = %q, want web-1", got)
70		}
71	}
72	
73	func TestPathSourceListFrom(t *testing.T) {
74		engineErr := errors.New("cannot connect")
75		okOS := "Debian GNU/Linux 13 (trixie)"
76		running := []docker.Container{
77			ctr(idWeb, "web-1", "nginx", "running"),
78			ctr(idDB, "db", "postgres", "paused"),
79			ctr(idAPI, "api", "app", "running"),
80			ctr("xyz", "bad-id", "x", "running"),
81		}
82		tests := []struct {
83			name       string
84			engine, os string
85			osErr      error
86			cs         []docker.Container
87			psErr      error
88			wantNames  []string
89			wantNote   string
90		}{
91			{"running only, sorted, paused and bad ID left out", "docker", okOS, nil, running, nil, []string{"api", "web-1"}, ""},
92			{"no containers at all", "docker", okOS, nil, nil, nil, []string{}, noteNoContainer},
93			{"none running", "docker", okOS, nil, []docker.Container{
94				ctr(idDB, "db", "postgres", "exited"),
95				ctr(idHos, "p", "x", "restarting"),
96				ctr(idWeb, "c", "x", "created"),
97				ctr(idAPI, "d", "x", "dead"),
98			}, nil, []string{}, noteNoContainer},
99			{"only a bad ID running", "docker", okOS, nil, []docker.Container{ctr("xyz", "a", "i", "running")}, nil, []string{}, noteNoContainer},
100			{"os read failed", "docker", "", engineErr, running, nil, []string{}, noteNoEngine},
101			{"ps failed", "docker", okOS, nil, nil, engineErr, []string{}, noteNoEngine},
102			{"ps failed even with rows", "docker", okOS, nil, running, engineErr, []string{}, noteNoEngine},
103			{"docker desktop", "docker", "Docker Desktop", nil, running, nil, []string{}, noteDesktop},
